"""Where uploads go (generated by Shikshya, P1b.6 R2): a private S3-compatible bucket when the app is given one
(settings.py, STORAGE_BUCKET). Pages show an upload through a link signed for an hour; a seeded picture is a path from
the built frontend (/img/...) and is served as it is."""
from storages.backends.s3 import S3Storage


class UploadStorage(S3Storage):
    def url(self, name, parameters=None, expire=None, http_method=None):
        if name and str(name).startswith("/"):
            return str(name)
        return super().url(name, parameters=parameters, expire=expire, http_method=http_method)


# PX.269: without a bucket, uploads stay on this server's disk and get links signed for an hour all the same;
# config/urls.py serves a file only to a signed link or when a record anyone may read holds it.
from django.core import signing  # noqa: E402
from django.core.files.storage import FileSystemStorage  # noqa: E402

MEDIA_SALT = 'shikshya-upload'
MEDIA_MAX_AGE = 3600


def signed_query(name):
    """The part of an upload's link that shows this server gave it out."""
    return signing.TimestampSigner(salt=MEDIA_SALT).sign(str(name))[len(str(name)) + 1:]


def link_is_signed(name, token):
    """True when the token was given out for this file within the hour."""
    try:
        signing.TimestampSigner(salt=MEDIA_SALT).unsign('%s:%s' % (name, token), max_age=MEDIA_MAX_AGE)
    except signing.BadSignature:
        return False
    return True


class SignedFileStorage(FileSystemStorage):
    """Uploads on this server's disk: pages show them through a link signed for an hour, like a bucket's."""

    def url(self, name):
        if name and str(name).startswith('/'):
            return str(name)
        return '%s?s=%s' % (super().url(name), signed_query(name))
